# Lesson 7 of MKTG90037: the business model (Week 3, first half). Brand: Hilton (FY2025 10-K facts; blocks are the course's reading
# of the filings). Instruments: Hilton on the nine blocks (Place), model or strategy (Tag).
from mk import *  # noqa: F403


def L07(CID):
    SK = 'mk.business-model'
    zones = [dict(id='seg', label=T('Customer segments', '客户细分')), dict(id='vp', label=T('Value propositions', '价值主张')), dict(id='ch', label=T('Channels', '渠道')),
             dict(id='rel', label=T('Customer relationships', '客户关系')), dict(id='rev', label=T('Revenue streams', '收入来源')), dict(id='res', label=T('Key resources', '核心资源')),
             dict(id='act', label=T('Key activities', '关键活动')), dict(id='par', label=T('Key partners', '重要伙伴')), dict(id='cost', label=T('Cost structure', '成本结构'))]
    chips = [
        dict(id='h1', label=T('Guests booking stays, leisure and business', '订房的客人，休闲与商务'), zone='seg', why=T('One side of a two-sided model.', '双边模式的一边。')),
        dict(id='h2', label=T('Hotel owners who want a brand and a system to operate under', '想要品牌和运营体系的酒店业主'), zone='seg', why=T('The owners are Hilton’s customers too: they pay the fees (a reading).', '业主也是 Hilton 的客户：他们付费用（解读）。')),
        dict(id='h3', label=T('A trusted brand and a consistent stay (guests); demand, standards and systems under licence (owners)', '可信的品牌和一致的住宿体验（对客人）；需求、标准和体系的授权（对业主）'), zone='vp', why=T('One proposition for each segment.', '每个细分一套主张。')),
        dict(id='h4', label=T('Hilton’s own booking channels, which carry member benefits', 'Hilton 自己的预订渠道，附带会员福利'), zone='ch', why=T('Members who book through Hilton channels get the benefits (10-K).', '通过 Hilton 渠道预订的会员享受福利（年报）。')),
        dict(id='h5', label=T('Hilton Honors: 243 million members at the end of 2025', 'Hilton Honors：2025 年底 2.43 亿会员'), zone='rel', why=T('A loyalty relationship, with tiers of benefit.', '一种忠诚关系，福利分层。')),
        dict(id='h6', label=T('Base and incentive management fees, and franchise fees', '基础与激励管理费，以及特许经营费'), zone='rev', why=T('Fees for running or licensing hotels (10-K).', '运营或授权酒店收取的费用（年报）。')),
        dict(id='h7', label=T('Revenue from the 46 hotels it owns (USD 1,233 million of ownership revenue in 2025)', '自有 46 家酒店的收入（2025 年自有业务收入 12.33 亿美元）'), zone='rev', why=T('Ownership revenue, a small part of the whole (10-K).', '自有酒店收入，只占整体一小部分（年报）。')),
        dict(id='h8', label=T('The brands and licensed intellectual property', '品牌与授权的知识产权'), zone='res', why=T('What the franchise sells: the right to use the brand.', '特许经营卖的东西：使用品牌的权利。')),
        dict(id='h9', label=T('The Honors member base and booking platform', 'Honors 会员基础和预订平台'), zone='res', why=T('Resources that bring demand to owners’ hotels.', '给业主的酒店带来需求的资源。')),
        dict(id='h10', label=T('Setting standards, running distribution and the loyalty platform', '制定标准、运营分销和忠诚平台'), zone='act', why=T('Platform and standards work, not owning buildings.', '平台和标准工作，不是拥有建筑。')),
        dict(id='h11', label=T('Hotel owners and franchisees; card partners that fund Honors', '酒店业主与加盟商；为 Honors 出资的信用卡伙伴'), zone='par', why=T('Honors is funded partly by strategic partners such as card providers (10-K).', 'Honors 的资金部分来自信用卡机构等战略伙伴（年报）。')),
        dict(id='h12', label=T('Costs of managed hotels that owners reimburse: USD 7,085 million of revenue in 2025', '业主偿付的受托管理酒店成本：2025 年有 70.85 亿美元收入'), zone='cost', why=T('Cost reimbursement revenue appears in the 10-K: those costs are passed through to owners.', '年报里有“成本偿付收入”：这些成本转由业主承担。')),
    ]
    cats = [dict(id='bm', label=T('Business model (what it is now)', '商业模式（现在是什么）')), dict(id='str', label=T('Strategy (what it aims to become)', '战略（想成为什么）')), dict(id='rev', label=T('Only a revenue model', '只是收入模式'))]
    items = [
        dict(text=T('“We earn fees from hotels owned by others and send them guests through our brand.”', '“我们向别人拥有的酒店收费，并通过品牌给它们送客人。”'), cat='bm', why=T('It describes how the firm creates, delivers and captures value today.', '它描述了企业今天怎样创造、交付并获取价值。')),
        dict(text=T('“In five years we want to be the biggest hotel operator in the region.” (an illustration)', '“五年内我们要成为本地区最大的酒店运营商。”（举例）'), cat='str', why=T('A future aim. A business model is a snapshot of the present.', '是未来的目标。商业模式是当下的快照。')),
        dict(text=T('“Guests pay per night, owners pay a percentage of room revenue.”', '“客人按晚付费，业主付房费收入的一定比例。”'), cat='rev', why=T('Only how money comes in: one block, not the whole model.', '只讲钱怎么进来：一个模块，不是整个模式。')),
        dict(text=T('“We will enter the budget segment to beat rivals.” (an illustration)', '“我们要进入经济型市场去击败对手。”（举例）'), cat='str', why=T('A choice about where and how to compete.', '关于在哪里、怎样竞争的选择。')),
        dict(text=T('“Our customers are guests and owners; our key partner network is owners and card providers.”', '“我们的客户是客人和业主；重要伙伴网络是业主和信用卡机构。”'), cat='bm', why=T('It names blocks of the canvas and how they connect.', '它点出了画布上的模块及其联系。')),
    ]
    return dict(
        id=f'{CID}-business-model',
        title=T('How does the whole business make a promise and a profit?', '整个业务怎样既兑现承诺，又赚到钱？'),
        description=T('Put Hilton on the nine blocks of the Business Model Canvas, and keep a business model apart from a strategy and a revenue model.', '把 Hilton 放到商业模式画布的九个模块上，并把商业模式和战略、收入模式区分开。'),
        minutes=45,
        skills=[{'id': SK, 'name': T('Explaining and applying the business model canvas', '解释并应用商业模式画布')}],
        misconceptions=[
            {'id': 'bm-is-strategy', 'description': T('a business model is the same as a strategy', '商业模式就是战略')},
            {'id': 'bm-is-revenue', 'description': T('a business model is how the firm makes money', '商业模式就是怎么赚钱')},
        ],
        steps=[
            read('puzzle', T('A hotel company that owns almost no hotels', '一家几乎不拥有酒店的酒店公司'),
                 p(T("At the end of 2025 Hilton had 873 managed and 8,239 franchised properties, and **46** hotels it owned. Its revenue that year was USD 12,039 million, and a large part of it was costs that owners paid back to it. A hotel company that owns 46 hotels can still be one of the biggest in the world.",
                     "2025 年底，Hilton 有 873 家受托管理的、8,239 家特许经营的物业，而自己拥有的酒店只有 **46** 家。当年收入 120.39 亿美元，其中很大一部分是业主偿还给它的成本。一家只拥有 46 家酒店的酒店公司，也可以是全球最大的之一。")),
                 p(T("What is the business, then, if not buildings? That question is what a **business model** answers.", "那么，如果不是建筑，这门生意到底是什么？这正是**商业模式**要回答的问题。")), chapter=CH['puzzle']),
            predict('guess', SK, T("Where does most of Hilton’s fee income come from: running a hotel for an owner, or licensing the brand to a franchisee?", "Hilton 的费用收入主要来自哪里：为业主运营酒店，还是向加盟商授权品牌？"),
                    [(T("Both, in different mixes: it manages some hotels for a fee and licenses the brand to far more", "两者都有，比例不同：它收费管理一部分酒店，授权品牌的则多得多"), True),
                     (T("Owning hotels and renting rooms", "拥有酒店并出租客房"), T("Only 46 hotels are owned.", "自有的只有 46 家。")),
                     (T("Selling toiletries", "卖洗漱用品"), T("Not a business line in the report.", "不是年报里的业务线。")),
                     (T("Advertising to guests", "向客人投放广告"), T("Not named as a revenue line.", "没有被列为收入项。"))],
                    T("Fees from managing and franchising, plus a smaller ownership business. Now place the whole thing on the canvas.", "来自管理与特许经营的费用，加上较小的自有业务。现在把整个模式放到画布上。")),
            read('touch', T('Hilton on the canvas', '把 Hilton 放到画布上'),
                 p(T("Twelve statements about Hilton, built from its 2025 annual report. The way they are grouped into blocks is the course’s reading.", "关于 Hilton 的十二条陈述，来自它 2025 年的年报。它们怎样归入各模块，是本课程的解读。")),
                 place(T('Twelve statements about Hilton to place on the nine blocks of the canvas.', '十二条关于 Hilton 的陈述，放到画布的九个模块上。'), zones, chips, cols=3,
                       done=T("Notice what the canvas shows at once: **two customer groups** (guests and owners) with one platform between them, **revenue that is mostly fees**, and **costs largely passed through**. That is why it can be big with few buildings.", "注意画布一眼就能看出的：**两类客户**（客人和业主）之间是同一个平台，**收入多半是费用**，**成本大部分转给业主**。所以它可以楼少而盘大。"), height=1280),
                 chapter=CH['touch']),
            read('touch2', T('Model, strategy or revenue?', '是模式、战略，还是收入？'),
                 p(T("Three things are often written as if they were one. Five statements, some made up as illustrations.", "三样东西常被写成一样。下面五条陈述，有些是为说明而编的。")),
                 tag(T('Five statements to tag as business model, strategy or only a revenue model.', '五条陈述，标为商业模式、战略或只是收入模式。'), cats, items,
                     done=T("A business model **describes what a firm is at a given moment**; a strategy is **what it aims to become**; a revenue model is **one block** of the model. Confusing them is the classic Explain error.", "商业模式**描述企业在某一时刻是什么**；战略是**它想成为什么**；收入模式只是模式的**一个模块**。把它们混淆，是“解释”里的经典错误。"), height=560)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("A **business model** is a conceptual, not financial, model of how an enterprise **creates** value for customers, **delivers** it, and **captures** value, by enticing customers to pay and converting payments into profit (Teece). It is **not** a strategy, a revenue model, a business concept, an economic model or a process model, though it is often mistaken for them: it describes what a company is now, while strategy reflects what it aims to become (DaSilva and Trkman). Magretta: it is like a story, with precise characters, plausible motives, and a plot that turns on an insight about value.",
                     "**商业模式**是关于企业怎样为顾客**创造**价值、**交付**价值并**获取**价值的概念性（非财务）模型：吸引顾客付费，再把付款转化为利润（Teece）。它**不是**战略、收入模式、商业概念、经济模型或流程模型，虽然常被误认为是它们：它描述企业现在是什么，而战略反映它想成为什么（DaSilva 和 Trkman）。Magretta：它像一个故事，有精确的人物、可信的动机，以及围绕价值洞察展开的情节。")),
                 p(T("The **nine blocks** of the canvas, with the choices inside each. Open the box for the list you need to recall.", "画布的**九个模块**，以及每个模块里的选项。需要回忆时展开清单。")),
                 details(T('The nine blocks and their types', '九个模块及其类型'),
                         ul(T("**Customer segments**: mass, niche, diversified, multi-sided, segmented (use the week-2 bases)", "**客户细分**：大众、利基、多元、多边、细分（用第 2 周的依据）"),
                            T("**Value propositions**: performance, price, design, brand or status, convenience, risk reduction", "**价值主张**：性能、价格、设计、品牌/地位、便利、降低风险"),
                            T("**Channels**: direct and indirect; what flows through (goods, title, money); scalable; support; whether they meet customer needs", "**渠道**：直接与间接；流动的是什么（货、所有权、钱）；可扩展；支持；能否满足顾客需求"),
                            T("**Customer relationships**: personal assistance, dedicated personal assistance, self-service, automated service, communities, co-creation; loyalty tiers give different support levels", "**客户关系**：人工协助、专属人工协助、自助、自动化服务、社群、共同创造；忠诚等级对应不同支持"),
                            T("**Revenue streams**: sale, pay-as-you-go, leasing, freemium, subscription, advertising or sponsorship (two-sided markets), and hybrids (a car-sharing firm renting by the hour)", "**收入来源**：销售、按量付费、租赁、免费增值、订阅、广告或赞助（双边市场），以及混合模式（按小时租车的共享汽车公司）"),
                            T("**Key resources**: physical, intellectual, human, financial", "**核心资源**：实物、知识、人力、资金"),
                            T("**Key activities**: production, problem solving, platform or network management, marketing, sales and service; should be valuable, unique and sustainable", "**关键活动**：生产、解决问题、平台或网络管理、营销销售与服务；应有价值、独特、可持续"),
                            T("**Key partners**: outsourcing business functions, and managing direct suppliers; benefits are focus and scale, less risk, access to resources and faster entry to markets", "**重要伙伴**：外包业务职能，和管理直接供应商；好处是聚焦和规模、降低风险、获取资源、更快进入市场"),
                            T("**Cost structure**: cost-driven or value-driven; fixed and variable costs; economies of scale and scope", "**成本结构**：成本驱动或价值驱动；固定与可变成本；规模经济与范围经济"))),
                 h(T('A snapshot, but the film keeps rolling', '这是快照，但电影还在放')),
                 p(T("A model changes. Taking a football club as a case (Demil and Lecocq), three linked parts jointly decide revenue and cost: **resources and competences**, **organisation**, and **value propositions**. Change can be **voluntary** (a new stadium, a naming deal, a new shirt sponsor) or **emerging** from outside (a league rule, a court ruling, a financial crisis hitting premium seats). The model must keep these parts consistent as it changes.", "模式会变化。以一家足球俱乐部为例（Demil 和 Lecocq），三个相互联系的部分共同决定收入和成本：**资源与能力**、**组织**、**价值主张**。变化可以是**主动的**（新球场、冠名合同、新球衣赞助商），也可以是外部**涌现**的（联赛规则、法院裁决、金融危机冲击高端座位）。变化中必须保持这几部分一致。")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Take **Who Gives a Crap** and describe its model on only **three blocks**: customer segment, channel and revenue, and one cost that its giving creates. Use true facts only (direct to consumer from its website; made mainly by partner manufacturers abroad; 50% of profits donated; free carbon-neutral shipping on larger orders). Four sentences.", "以 **Who Gives a Crap** 为例，只用**三个模块**描述它的模式：客户细分、渠道与收入，以及它的捐赠带来的一项成本。只用真实事实（通过自己的网站直销；主要由海外合作厂商生产；50% 利润捐赠；大额订单免运费、碳中和配送）。写四句话。"),
                    [T("Names a segment and the direct-to-consumer channel", "说出细分和直销渠道"), T("States how it earns (selling the product online) and that half of the profit is given away", "说明怎么赚钱（线上卖产品）以及一半利润捐出"),
                     T("Links a cost: shipping offsets, or profit that cannot be reinvested", "联系到一项成本：配送抵消，或不能再投资的利润"), T("Says how the blocks connect (the giving is part of the proposition, so it is a cost and a draw)", "说明模块怎样联系（捐赠是价值主张的一部分，所以既是成本也是吸引力）")],
                    T("Who Gives a Crap serves values-led households through one channel, its own website, which gives it direct contact and no retailer margin to share. It earns by selling the paper online and commits 50% of profits to water and sanitation projects. That giving is a cost, but it is also the proposition: it draws the segment and justifies the price, so the blocks are tied together. A further cost is shipping, which it offsets so that delivery on larger orders is carbon neutral.",
                      "Who Gives a Crap 通过自己的网站这一个渠道服务价值观导向的家庭，这让它与顾客直接联系，也不用分出零售商的利润。它靠在线卖卷纸赚钱，并承诺把 50% 的利润投给供水和卫生项目。这项捐赠是成本，但也是价值主张：它吸引这个细分并支撑价格，所以各模块是连在一起的。另一项成本是运费，它通过抵消让大额订单的配送实现碳中和。"),
                    T("Link the blocks: a canvas is a system.", "把模块连起来：画布是一个系统。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("An answer to “describe Hilton’s business model” says: “Hilton will expand into the budget segment and become the largest hotel company.” What is wrong?", "“描述 Hilton 的商业模式”的答案写道：“Hilton 将进入经济型市场，成为最大的酒店公司。”问题在哪？"),
                   [(T("That is a strategy: a future aim, where a model describes how it creates, delivers and captures value now", "那是战略：未来的目标，而模式描述它现在怎样创造、交付并获取价值"), True),
                    (T("Nothing, strategy and model are the same", "没问题，战略和模式是一回事"), T("DaSilva and Trkman say they are different.", "DaSilva 和 Trkman 说它们不同。")),
                    (T("It should list revenue only", "应该只列收入"), T("That is the revenue model, a single block.", "那是收入模式，只是一个模块。"))],
                   T("Model is now, strategy is next.", "模式是现在，战略是下一步。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 6: which block of the canvas does a value proposition fill?", "来自第 6 课：价值主张填画布的哪个模块？"),
                   [(T("Value propositions, paired with a customer segment", "价值主张，与某个客户细分配对"), True), (T("Key resources", "核心资源"), T("Resources are what you have to deliver it.", "资源是你兑现它所需要的东西。"))], T("One proposition for each segment.", "每个细分一套主张。"), first=True),
            recall('r2', SK, T("From lesson 4: Hilton’s Honors member base is best described as a…", "来自第 4 课：Hilton 的 Honors 会员基础，最好描述为……"),
                   [(T("core competence-like resource that is hard to copy", "接近核心能力、难以复制的资源"), True), (T("a feature any rival can ship", "任何对手都能做出的功能"), T("Not with 243 million members.", "有 2.43 亿会员就不是。"))], T("VRIN.", "VRIN。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain what a business model is, with its main components. (b) Apply the canvas to Hilton Hotels in Australia. (c) Make two recommendations.", "题目。(a) 解释商业模式是什么及其主要组成。(b) 把画布应用到澳大利亚的 Hilton 酒店。(c) 给出两条建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("How an enterprise creates, delivers and captures value (Teece)", "企业怎样创造、交付、获取价值（Teece）"), T("Not a strategy or revenue model: describes now versus aims to become", "不是战略或收入模式：现在是什么，对比想成为什么"),
                         T("The nine blocks named correctly", "正确说出九个模块"), T("It changes over time", "它会随时间变化")],
                        T("A business model is a conceptual model of how an enterprise creates value for customers, delivers it, and captures value by getting paid and turning payments into profit (Teece). It is not a strategy, which is what a firm aims to become, nor a revenue model, which is one part of it. The canvas has nine blocks: customer segments, value propositions, channels, customer relationships, revenue streams, key resources, key activities, key partners and cost structure. A model is a snapshot of a firm now, and it must be kept consistent as the firm changes.",
                          "商业模式是关于企业怎样为顾客创造价值、交付价值，并通过收款并把收款转为利润来获取价值的概念性模型（Teece）。它不是战略（企业想成为什么），也不是收入模式（它的一部分）。画布有九个模块：客户细分、价值主张、渠道、客户关系、收入来源、核心资源、关键活动、重要伙伴和成本结构。模式是企业当下的快照，企业变化时必须保持各部分一致。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Uses at least five blocks for Hilton, correctly", "为 Hilton 正确使用至少五个模块"), T("True facts: 8,239 franchised, 873 managed, 46 owned; fees; 243 million Honors members; cost reimbursement", "真实事实：8,239 家特许、873 家管理、46 家自有；费用；2.43 亿 Honors 会员；成本偿付"),
                         T("Connects blocks with cause and effect (asset-light model, two customer groups, loyalty feeding demand)", "用因果连接各模块（轻资产模式、两类客户、忠诚计划带来需求）"), T("Distinguishes Australia where it can, or says facts are global", "能区分澳大利亚就区分，否则说明事实是全球的")],
                        T("The facts here are Hilton’s global figures. Hilton serves two segments, guests and the owners of hotels, and gives each a proposition: a trusted brand and consistent stay for guests, and demand, standards and systems under licence for owners. At the end of 2025 about 8,239 of its properties were franchised and 873 managed against 46 owned, so revenue is mostly fees plus reimbursed costs. The channels are its own booking channels, which carry Honors benefits, and Honors with 243 million members is the customer relationship that feeds demand to owners’ hotels. Key partners are the owners and card providers that fund Honors. Because owners pay for buildings and reimburse running costs, Hilton’s cost structure is light, which explains how it can be large with few hotels owned; the same structure makes it depend on owners keeping standards.",
                          "这里的事实是 Hilton 的全球数据。Hilton 服务两个细分，客人和酒店业主，并给各自一个主张：对客人是可信的品牌和一致的住宿体验，对业主是需求、标准和体系的授权。2025 年底约 8,239 家物业是特许经营、873 家受托管理，对比自有 46 家，所以收入主要是费用加上偿付的成本。渠道是它自己的预订渠道，附带 Honors 福利；拥有 2.43 亿会员的 Honors 是给业主酒店输送需求的客户关系。重要伙伴是业主和为 Honors 出资的信用卡机构。因为业主出资建楼并偿付运营成本，Hilton 的成本结构很轻，这解释了它为何自有酒店很少却能规模巨大；同样的结构也让它依赖业主守住标准。")),
                       (T("Write the **Recommend** part: exactly two.", "写**建议**部分：恰好两条。"),
                        [T("Exactly two from the analysis (dependence on owners; value of Honors)", "恰好两条，从分析里推出（对业主的依赖；Honors 的价值）"), T("Each actionable", "每条可执行"), T("A risk named", "点出风险")],
                        T("First, give owners clearer proof of what Hilton demand is worth to them, for example by showing the share of bookings that come through Honors and Hilton channels, because owners are the customer who pays and can leave. The risk is revealing commercial data, so share it in owner reports only. Second, extend Honors earning to partner experiences that keep members in the ecosystem between stays. The risk is partner quality harming the brand, so choose few and audit them.",
                          "第一，向业主更清楚地证明 Hilton 带来的需求对他们值多少，比如展示通过 Honors 和 Hilton 渠道来的订单份额，因为业主是付费的、也可以离开的客户。风险是披露商业数据，所以只在业主报告里提供。第二，把 Honors 积分扩展到合作伙伴的体验上，让会员在两次住宿之间仍留在这个生态里。风险是合作方的质量损害品牌，所以少选并加以审核。")),
                       ),
    )
